function reset(){workflowStage='all';registerMeta={facets:{},navigation:null};fileHistory=false;epoch++;actor=null;cap=null;rows=[];requests=[];profile=null;request=null;clientContext=null;mode='list';tab='personal';busy=false;notice='';files=[];circulars=[];review=null;preview=null;report=null;importJob=null;linkedTasks=null;taskError='';drafts={};}
function sync(){const who=ABCentral?.actor?.id;if(who!==actor){reset();actor=who;}}
async function api(path,method='GET',body){const n=epoch,who=ABCentral?.actor?.id;const r=await ABCentral.api(path,method,body,method==='GET'?undefined:ids());if(n!==epoch||who!==ABCentral?.actor?.id)throw Error('staleSession');return r;}
function draw(){if(app.state.currentPage==='vehicles')render();}
function show(msg){notice=msg;const n=document.getElementById('ve-notice');if(n)n.textContent=msg;}
async function load(){if(busy)return;busy=true;try{cap=await api('vehicles/capabilities');if(cap.available){const saved=await api('vehicle-preferences');if(Array.isArray(saved.columns)&&saved.columns.length)prefs=saved;const old=prefs.filters||{},g=JSON.parse(old.grid||'{}');g.values={...g.values};if(old.statuses)g.values.status=old.statuses.split(',');prefs.filters={q:old.q||'',companies:old.companies||'',licenseId:old.licenseId||'',grid:JSON.stringify(g)};await list(true);const r=await api('vehicle-requests');requests=r.rows;references={investors:r.investors,employees:r.employees,registryAvailable:r.registryAvailable};circulars=(await api('vehicle-circulars')).rows;}}catch(err){if(err.message!=='staleSession')notice=error(err.message);}finally{busy=false;draw();}}
