function leave(){for(const form of document.querySelectorAll('.ve-form[data-track-changes]')){if(form._saving)return false;if(!RecordProfile.confirmLeave(form))return false;}return true;}
async function open(id){if(!leave())return;if(mode!=='profile')recordReturnScroll=window.scrollY;vehicleEditing=false;fileHistory=false;const {grid,...query}=prefs.filters;const nav=await api('registers/vehicles?'+new URLSearchParams({query:JSON.stringify(query),grid:grid||'{}',seek:id}));registerMeta.navigation=nav.navigation;linkedTasks=null;taskError='';profile=await api('vehicles/'+id);files=rights('documents')?(await api('vehicles/'+id+'/files')).rows:[];request=null;mode='profile';tab='personal';review=null;preview=null;drafts={};draw();window.scrollTo(0,0);}
async function loadLinkedTasks(){const id=profile.id,requestId=profile.requestId||profile.request?.id;linkedTasks=null;taskError='';tab='tasks';draw();try{const r=await api('personnel/tasks?companyId='+encodeURIComponent(profile.companyId));if(profile?.id===id)linkedTasks=r.rows.filter(x=>x.payload?.vehicleId===id||x.source_id===id||x.source_type==='vehicle_registration'&&x.source_id===requestId);}catch{if(profile?.id===id)taskError=t('تعذر عرض المهام ضمن الصلاحيات الحالية.','Tasks could not be displayed with the current permissions.');}finally{if(profile?.id===id&&tab==='tasks')draw();}}
