async function assignRegistration(){const id=request.id,companyId=request.companyId;const [staff,tasks]=await Promise.all([api('personnel/employees?companyId='+encodeURIComponent(companyId)),api('personnel/tasks?companyId='+encodeURIComponent(companyId))]);const existing=tasks.rows.find(x=>x.source_type==='vehicle_registration'&&x.source_id===id);if(existing&&['Completed','Closed'].includes(existing.state)){show(t('مهمة التسجيل محفوظة ومغلقة.','The registration task is retained and closed.'));return;}CenterForms.form(t('إسناد تسجيل المركبة لمسؤول العلاقات العامة','Assign vehicle registration to the PRO'),[{name:'employeeId',ar:'الموظف المسؤول',en:'Responsible employee',value:existing?.employee_id,options:staff.rows.filter(x=>x.state!=='Ended'&&x.userId).map(x=>({id:x.id,name:(getLocale()==='ar'?x.nameAr:x.nameEn)+' — '+x.jobTitle+' #'+x.number}))},...(existing?[]:[{name:'dueOn',ar:'موعد الإنجاز',en:'Due date',type:'date',value:new Date().toISOString().slice(0,10)}]),{name:'note',ar:'سبب الإسناد',en:'Assignment reason'}],async(d,key)=>{if(existing)await ABCentral.api('personnel/tasks/'+existing.id+'/action','POST',{action:'reassign',employeeId:d.employeeId,note:d.note,revision:existing.revision},key);else await ABCentral.api('vehicle-requests/'+id+'/registration-task','POST',d,key);show(t('تم حفظ المهمة المرتبطة؛ لا تُغلق إلا بالتحقق من التسجيل الفعلي.','Linked task saved; completion requires verified vehicle registration.'));});}
async function bankContractView(){const r=request,data=await api('vehicle-requests/'+r.id+'/bank-contract'),dialog=document.createElement('dialog');dialog.dataset.centerOwned='1';dialog.className='record-form-dialog';dialog.innerHTML=`<div class="section-head"><h2>${e(data.number)} — ${e(data.lender)} → ${e(co(data.borrowerCompanyId))}</h2><button type="button" data-bank-close class="ghost-btn">${t('إغلاق','Close')}</button></div><p>${t('البنك يتعاقد مع الشركة؛ عقد العميل مستقل. الربط لا ينشئ قيداً أو صرفاً جديداً.','Bank contracts with the company; customer agreement is independent. Linking creates no posting or payment.')}</p><dl class="hr-details">${[['أصل قرض البنك','Bank principal',data.principal],['المستلم فعلياً','Actual drawdown',data.received],['أصل مسدد للبنك','Bank principal repaid',data.principalRepaid],['أصل قائم','Principal outstanding',data.principalOutstanding],['فوائد مدفوعة','Interest paid',data.interestPaid],['رسوم مدفوعة','Fees paid',data.feesPaid],['صافي تدفق عقد البنك','Bank contract net cash flow',data.netBankContractCash],['أصل عقد العميل لصالح الشركة','Customer principal payable to company',data.customerFinancingPrincipal],['أقساط العميل','Customer installment total',data.customerInstallmentTotal]].map(([ar,en,value])=>`<div><dt>${e(t(ar,en))}</dt><dd>${e(value)} ${e(data.currency)}</dd></div>`).join('')}</dl>${table([t('قسط البنك','Bank installment'),t('الاستحقاق','Due'),t('المبلغ','Amount')],data.scheduled.map(x=>[e(x.installment),e(x.dueOn),e(x.amount)]))}<h3>${t('الحركات الفعلية المرتبطة','Linked actual operations')}</h3>${table([t('النوع','Type'),t('المبلغ','Amount'),t('القسط','Installment'),t('التوثيق','Note')],data.links.map(x=>[e(x.category),e(x.amount),e(x.installment||'—'),e(x.note)]))}<button type="button" class="secondary-btn" data-bank-link>${t('ربط حركة مالية معتمدة','Link approved financial operation')}</button><button type="button" class="ghost-btn" data-bank-books>${t('دفتر الشركة وتقارير الربح والتدفق النقدي','Company ledger, profit and cash-flow reports')}</button>`;document.body.append(dialog);dialog.querySelector('[data-bank-close]').onclick=()=>dialog.remove();dialog.querySelector('[data-bank-books]').onclick=async()=>{dialog.remove();await LedgerUI.openNotification(r.companyId);};dialog.querySelector('[data-bank-link]').onclick=()=>CenterForms.form(t('ربط حركة بعقد البنك — لا صرف جديد','Link bank contract operation — no new payment'),[{name:'category',ar:'التصنيف المحاسبي الفعلي',en:'Actual accounting category',options:[{id:'drawdown',name:t('استلام أصل قرض البنك — التزام','Loan drawdown — liability')},{id:'principal',name:t('سداد أصل قرض البنك — تخفيض الالتزام','Principal repayment — liability reduction')},{id:'interest',name:t('فائدة مدفوعة — مصروف معتمد','Paid interest — approved expense')},{id:'fee',name:t('رسوم بنك مدفوعة — مصروف معتمد','Paid bank fees — approved expense')}]},{name:'operationId',ar:'عملية بنكية معتمدة',en:'Approved bank operation',options:data.operations.map(x=>({id:x.id,name:x.kind+' — '+x.amount+' '+x.currency+' — '+x.reference+' — '+x.account_kind}))},{name:'installment',ar:'رقم القسط لسداد الأصل أو الفائدة',en:'Installment for principal/interest payment',type:'number',required:false},{name:'note',ar:'مرجع وتوثيق الارتباط بعقد البنك',en:'Evidence/reference linking this operation to bank agreement'},{name:'confirm',ar:'أؤكد ارتباط العملية بعقد البنك مع الشركة',en:'Confirm operation belongs to bank/company agreement',type:'checkbox',value:false}],async(d,key)=>{if(['principal','interest'].includes(d.category)&&d.installment)d.installment=Number(d.installment);else delete d.installment;await ABCentral.api('vehicle-requests/'+r.id+'/bank-contract/transactions','POST',d,key);dialog.remove();await bankContractView();});dialog.showModal();FloatingRecords.open(dialog,{close:()=>dialog.remove()});}
function reviewSummary(r){const data=[['رقم الطلب','Request number',r.requestNumber],['العميل / رقم الملف','Customer / file',(r.customerName||r.customerId)+' / '+(r.customerNumber||'')],['الشركة','Company',co(r.companyId)],['تاريخ الإنشاء','Created',WorkspaceUI.dateTime(r.createdAt)],['أنشأه','Created by',r.creatorName],['مصدر التمويل','Funding source',l(r.financeType)],['المستثمر','Investor',references.investors?.find(x=>x.id===r.investorId)?.name||'—'],['نوع المركبة','Vehicle type',r.vehicleType],['الماركة','Make',r.make],['الموديل','Model',r.model],['السنة','Year',r.year],['وصف وحالة المركبة','Description / condition',(r.description||'')+' '+(r.condition||'')],['قيمة المركبة','Vehicle value',r.approximateValue],['التمويل المطلوب','Requested principal',r.expectedFunding],['الدفعة الأولى','Down payment',r.downPayment||'0'],['الأشهر','Months',r.months],['القسط المتوقع','Expected installment',r.expectedMonthly||'—'],['إجمالي الأقساط','Installment total',r.installmentTotal||'—'],['رسوم مستقلة','Independent fees',r.independentFees||'0'],['فرق القيمة عن التمويل والدفعة','Value less principal and down payment',r.review?.vehicleFundingDifference],['فرق الإجمالي عن القسط × الأشهر','Total less installment × months',r.review?.installmentDifference],['فرق تمويلي تعاقدي بعد تكلفة البنك وقبل رسوم العميل والتكاليف الأخرى','Contractual financing spread after bank cost, before customer fees and other costs',r.review?.bankFinancingSpread],['القسط الأخير','Last installment',r.review?.lastInstallment]];return `<section class="content-panel"><h3>${t('ملف مراجعة التمويل','Funding review file')}</h3><dl class="hr-details">${data.map(([ar,en,v])=>`<div><dt>${e(t(ar,en))}</dt><dd>${e(v||'—')}</dd></div>`).join('')}</dl><p>${e(r.notes||'')}</p>${r.funds?.length&&r.registrationTaskPending?`<p role="status">${t('لم يعيّن مسؤول التسجيل بعد؛ استخدم إسناد مهمة العلاقات العامة لموظف مخول.','Registration officer not assigned; assign the PRO task to an authorized employee.')}</p>`:''}${r.exceptionReason?`<p>${t('سبب الاستثناء','Exception reason')}: ${e(r.exceptionReason)}</p>`:''}${r.fundingState==='Requested'&&r.review?.missing.length?`<p role="alert">${t('بيانات ناقصة قبل الاعتماد','Missing before approval')}: ${r.review.missing.map(k=>e(l(k))).join('، ')}</p>`:''}${r.financeType==='bank'&&r.reviewSchemaVersion===1&&r.bankSchedule?.length&&r.bankContractFinanceAllowed?button('bank-contract',t('عقد البنك المستقل وحركاته','Independent bank contract and actual operations')):''}${r.bankSchedule?.length?`<h3>${e(r.bankName)} → ${e(co(r.companyId))} — ${t('التزامات الشركة تجاه البنك — مستقلة عن عقد العميل','Company obligations to bank — independent of customer agreement')}</h3>${table([t('القسط','Installment'),t('الاستحقاق','Due'),t('المبلغ','Amount')],r.bankSchedule.map(x=>[e(x.installment),e(x.dueOn),e(x.amount)]))}<p>${t('جدول تعاقدي؛ القيود والسداد الفعلي من المالية وفق الحسابات المعتمدة.','Contractual schedule; actual postings and payments use Finance and approved account mappings.')}</p>`:''}<h3>${t('مستندات الطلب','Request documents')}</h3>${(r.documents||[]).map(d=>button('request-file',d.title,d.id)).join('')}${r.canEditReview?button('review-edit',t('استكمال بيانات المراجعة','Complete review data'))+(r.documentsAllowed?button('request-upload',t('إضافة مستند للطلب','Add request document')):''):''}<h3>${t('المراجعات والقرارات','Reviews and decisions')}</h3>${table([t('التاريخ','Date'),t('الإجراء','Action'),t('الملاحظة','Note')],(r.events||[]).filter(x=>['funding_decision','request_review_updated'].includes(x.kind)).map(x=>[e(WorkspaceUI.dateTime(x.createdAt)),e(x.after?.decision||x.kind),e(x.after?.reason||'')]))}</section>`;}
function registrations(){const r=request,p=rows.find(v=>v.requestId===r.id)||(r.vehicleId?{id:r.vehicleId,fileNumber:''}:null);return button('select',t('العودة إلى سجل الطلبات','Back to request register'),'requests')+`<h2>${t('طلب','Request')} #${e(r.requestNumber)}</h2><p>${l(r.financeType)} — ${r.reviewState==='Returned'?t('أعيد للمراجعة','Returned for review'):l(r.fundingState)} — ${e(co(r.companyId))}</p><p>${t('الموافقة ليست صرفاً؛ والتسجيل ليس إصدار فواتير.','Approval is not disbursement; registration is not invoicing.')}</p>`+reviewSummary(r)+(r.fundingState==='Requested'&&rights('funding_approve',r.companyId)?`<section class="content-panel"><h3>${t('القرار','Decision')}</h3>${form('funding-approve',[f('reason',t('ملاحظة اختيارية','Optional note'),'textarea','')],t('اعتماد الطلب','Approve request'),!r.review?.missing.length)}${form('funding-reject',[f('rejectionCode',t('سبب الرفض','Rejection reason'),'select','',[{id:'incomplete',name:t('بيانات غير مكتملة','Incomplete data')},{id:'affordability',name:t('عدم ملاءمة القدرة على السداد','Affordability')},{id:'policy',name:t('مخالفة السياسة المعتمدة','Policy requirements')},{id:'documents',name:t('مستندات غير مستوفاة','Document requirements')},{id:'other',name:t('أخرى','Other')}],true),f('reason',t('تفاصيل إضافية — مطلوبة عند اختيار أخرى','Additional details — required for Other'),'textarea','')],t('رفض الطلب','Reject request'))}${form('funding-return',[f('reason',t('المطلوب مراجعته','Required corrections'),'textarea','',null,true)],t('إعادة للمراجعة','Return for review'))}</section>`:'')+(r.fundingState==='Approved'&&!r.funds?.length&&rights('disburse',r.companyId)?form('disburse',[f('receiverId',t('الموظف المستلم المخول','Authorized receiving employee'),'select','',request.disbursement?.receivers||references.employees.filter(x=>x.receivingCompanies?.includes(r.companyId)),true),...(request.disbursement?.registrationEmployees?.length?[f('registrationEmployeeId',t('مسؤول التسجيل (اختياري؛ يبقى الإسناد معلقاً عند عدم الاختيار)','Registration officer (optional; assignment stays pending if omitted)'),'select','',request.disbursement.registrationEmployees)]:[]),f('method',t('طريقة الصرف','Disbursement method'),'select',r.reviewSchemaVersion===1?'transfer':'cash',choices(r.financeType==='investor'?['cheque','transfer']:['cash','cheque','transfer']),true),f('source',t('مرجع مصدر الأموال المعتمد: ','Approved funding reference: ')+l(r.financeType),'text',l(r.financeType),null,true),f('date',t('التاريخ','Date'),'date',new Date().toISOString().slice(0,10),null,true),f('paymentOperationId',t('عملية الصرف الفعلية المعتمدة','Actual posted payment'),'select','',request.disbursement?.payments?.map(x=>({id:x.id,name:(request.disbursement.banks.find(b=>b.id===x.bank_account_id)?.name||'')+' — '+x.amount+' '+x.currency+' — '+x.reference})),false),...(r.reviewSchemaVersion===1?[f('cashJournalId',t('صرف الصندوق المثبت بقيد معتمد','Posted cash funding journal'),'select','',request.disbursement?.cashPayments||[]),f('documentVersionId',t('إثبات الصرف النقدي المفحوص','Scanned cash payment proof'),'select','',request.disbursement?.cashProofs||[]),f('cashConfirmed',t('أؤكد خروج النقد فعلياً؛ الحفظ لا ينشئ صرفاً','Confirm actual cash handover; saving creates no payment'),'checkbox',false)]:[]),f('evidence',t('توثيق الصرف','Disbursement evidence'),'textarea','',null,true)]):'')+table([t('العهدة','Custody'),t('الحالة','State'),t('تأكيد المستلم','Receiver confirmation')],(r.funds||[]).map(f=>[e(f.amount)+' '+e(f.currency),e(l(f.state)),f.state==='AwaitingReceipt'&&f.receiverId===actor?button('receive-funds',t('أؤكد الاستلام الفعلي','Confirm actual receipt'),f.id):'—']))+button('assign-registration-task',t('مهمة مسؤول العلاقات العامة','PRO registration task'))+(p?button('open',t('فتح ملف المركبة','Open vehicle'),p.id):(r.reviewSchemaVersion!==1||r.financeType==='cash'||r.funds?.some(f=>['Held','Settled'].includes(f.state)))?form('register',registrationFields({...r,vehicleType:r.vehicleType,currency:r.currency}),t('حفظ ملف المركبة','Save vehicle file'),rights('create',r.companyId)):`<p>${t('تفتح بيانات التسجيل النهائي بعد الاعتماد والصرف المثبت وتأكيد الاستلام.','Final registration opens after approval, posted disbursement and receipt confirmation.')}</p>`);}
function registrationFields(d={}){return [f('vehicleType',l('vehicleType'),'text',d.vehicleType||'',null,true),f('capacityTonnes',t('الحمولة بالطن','Capacity in tonnes'),'text',d.capacityTonnes||''),f('seats',t('عدد المقاعد','Seat count'),'text',d.seats||''),...['make','model','year','color'].map(k=>f(k,l(k),'text',d[k]||'')),f('emirate',l('emirate'),'select',d.emirate||'',(root.UaeAreaSeed?.emirates||[]).map(x=>({id:x.id,name:getLocale()==='ar'?(x.ar||x.nameAr||x.name_ar||x.id):(x.en||x.nameEn||x.name_en||x.id)}))),f('areaId',l('areaId'),'select',d.areaId||'',(ABCentral.areas||[]).filter(x=>(x.emirateId||x.emirate_id)===(d.emirate||'')).map(x=>({id:x.id,name:x.name||x.nameAr||x.name_ar||x.nameEn}))),...['plate','plateCode','vin'].map(k=>f(k,l(k),'text',d[k]||'')),f('registeredOn',l('registeredOn'),'date',d.registeredOn||''),f('ownershipExpiresOn',l('ownershipExpiresOn'),'date',d.ownershipExpiresOn||''),f('insuranceExpiresOn',t('انتهاء التأمين','Insurance expiry'),'date',d.insuranceExpiresOn||''),f('currency',l('currency'),'text',d.currency||'AED',null,true),f('notes',t('ملاحظات','Notes'),'textarea',d.notes||'')];}
function requestRows(){return `<p>${t('إنشاء طلب جديد من بروفايل العميل فقط. الطلبات أدناه لا تُعتبر مكتملة لمجرد الحفظ.','New requests originate only in a customer profile. Saved requests are not automatically completed.')}</p>`+table([t('الطلب','Request'),t('الشركة','Company'),t('التمويل','Funding'),t('الموافقة','Approval'),t('المركبة','Vehicle'),t('الإجراء','Action')],requests.filter(r=>mode!=='pending'||r.stage!=='completed').map(r=>{const v=rows.find(v=>v.requestId===r.id);return [e(r.requestNumber),e(co(r.companyId)),e(l(r.financeType)),e(l(r.fundingState))+' — '+e(l(r.stage)),v?button('open','#'+v.fileNumber,v.id):t('لم يسجل','Not registered'),button('request',t('متابعة الطلب','Continue request'),r.id)];}));}

function registerToolbar(){return `<div class="ve-actions"><button type="button" class="ghost-btn" data-rg-clear-all>${t('إزالة فلاتر الأعمدة','Clear column filters')}</button>${['excel','pdf','print','share'].map(format=>`<button type="button" class="ghost-btn" data-rg-export="${format}">${format==='print'?t('طباعة','Print'):format==='share'?t('مشاركة PDF','Share PDF'):format.toUpperCase()}</button>`).join('')}<label><input type="checkbox" data-rg-export-all>${t('جميع السجلات المسموحة (بدون الفلاتر)','All permitted records (ignore filters)')}</label></div>`;}
function bindRegister(){const host=document.querySelector('.ve-page,.vehicle-page');if(!host)return;RegisterTools.bind(host,JSON.parse(prefs.filters.grid||'{}'),async state=>{try{prefs.filters.grid=JSON.stringify(state);await list(true);await savePrefs();draw();}catch(err){notice=error(err.message);draw();}});host.querySelectorAll('[data-rg-export]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const {grid,...query}=prefs.filters;const q=new URLSearchParams({query:JSON.stringify(query),grid:grid||'{}',columns:prefs.columns.join(','),labels:JSON.stringify(prefs.columns.map(l)),locale:getLocale(),format:b.dataset.rgExport==='share'?'pdf':b.dataset.rgExport,all:String(!!host.querySelector('[data-rg-export-all]')?.checked)});await RegisterExport.run(await api('registers/vehicles?'+q),b.dataset.rgExport);}catch(err){notice=error(err.message);draw();}finally{b.disabled=false;}});}

function workflowKey(r){if(r.fundingState==='Rejected')return 'rejected';if(['Requested','Returned'].includes(r.fundingState))return 'approval';if(r.vehicleId&&r.registeredOn&&r.vehicleStatus==='Active'&&!r.funds?.some(x=>x.state==='AwaitingReceipt'))return 'ready';return 'procedures';}
