function renderPage(){sync();if(!ABCentral?.enabled)return `<section class="content-panel">${t('المركبات تتطلب Backend مركزياً؛ لا حفظ محلي.','Vehicles require the central backend; no local persistence.')}</section>`;if(!cap&&!busy)queueMicrotask(load);if(!cap)return `<section class="content-panel">${e(notice||t('جارٍ التحقق من الجاهزية…','Checking readiness…'))}</section>`;if(!cap.available)return `<section class="content-panel">${error('vehicleSchemaPending')}</section>`;return `<section class="content-panel ve-page"><p id="ve-notice" role="status">${e(notice)}</p>${mode==='new-request'?requestForm():mode==='request'&&request?registrations():mode==='profile'&&profile?`<div class="vehicle-register-background">${registerHTML()}</div><dialog id="vehicle-record-window" class="record-form-dialog">${profileHeader()}${profileHTML()}</dialog>`:mode==='requests'||mode==='pending'?requestRows():mode==='circulars'?circularHTML():mode==='configuration'?configHTML():mode==='reports'?reportHTML():mode==='import'?importHTML():registerHTML()}</section>`;}
function data(form){const d=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('input[type="checkbox"]'))if(!el.dataset.veMulti)d[el.name]=el.checked;for(const name of new Set([...form.querySelectorAll('[data-ve-multi]')].map(n=>n.dataset.veMulti)))d[name]=[...form.querySelectorAll('[data-ve-multi="'+name+'"]:checked')].map(n=>n.value).join(',');for(const [k,v]of Object.entries(d))if(k.endsWith('Id')&&v==='')delete d[k];return d;}
async function savePrefs(){if(ABCentral.viewAs)return;await api('vehicle-preferences','POST',prefs);}
async function refresh(){notice=t('تم الحفظ والتحقق على الخادم.','Saved and verified on server.');if(profile){const key=profile.id;profile=await api('vehicles/'+key);files=rights('documents')?(await api('vehicles/'+key+'/files')).rows:[];}const r=await api('vehicle-requests');requests=r.rows;references={investors:r.investors,employees:r.employees,registryAvailable:r.registryAvailable};if(request)request={...requests.find(r=>r.id===request.id),...await api('vehicle-requests/'+request.id)};if(request?.fundingState==='Approved'&&!request.funds.length&&rights('disburse',request.companyId))request.disbursement=await api('vehicle-requests/'+request.id+'/disbursement-options');await list(true);if(mode==='circulars')circulars=(await api('vehicle-circulars')).rows;draw();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function base64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
